#define f first
#define s second

mt19937_64 RNG(chrono::steady_clock::now().time_since_epoch().count());

void Solve() 
{
    int n, k; cin >> n >> k;

    vector <int> a(n + 1);
    for (auto &x : a) cin >> x;

    auto check = [&](int x){
        vector <int> b;
        for (int i = 0; i < x; i++){
            b.push_back(a[i] - k);
        }

        sort(b.begin(), b.end());

        for (int fix = 1; fix < x; fix++){
            // this is element where bob wins 

            deque <int> c;
            for (int i = 0; i <= fix; i++){
                c.push_back(b[i]);
            }

            assert(c.size() >= 2);

            while (c.size() != 2){
                c.pop_front(); 

                // find suffix which works 
                int sz = c.size();
                int works = 0;
                int sum = 0;
                for (int j = 1; j < sz; j++){
                    // sum(elements of c - current element) 
                    // this shud be >= k 
                    sum += c[sz - j];
                    int loss = sum - c[sz - j - 1] * j;
                    if (loss >= k){
                        works = sz - j;
                        break;
                    }
                }

                int have = k;

                // make everything = c[works]
                for (int j = works + 1; j < sz; j++){
                    have -= c[j] - c[works];
                    c[j] = c[works];
                }

                assert(have >= 0);
                for (int j = works; j < sz; j++){
                    c[j] -= have / (sz - works);
                }
                have %= (sz - works);

                for (int j = works; j < sz; j++){
                    if (have){
                        c[j]--;
                        have--;
                    }
                }

                for (int j = 0; j < sz - 1; j++){
                    assert(c[j] <= c[j + 1]);
                }
            }

            c.pop_front();
            if (c[0] <= 0) return false;
        }

        return true;
    };

    int l = 1, r = n + 1;   
    while (l != r){
        int mid = (l + r + 1) / 2;

        if (check(mid)) l = mid;
        else r = mid - 1;
    }

    cout << l << "\n";
}

