#define all(x) x.begin(),x.end()     
const ll MOD=998244353;
const ll MAX=10005;  
ll dp[MAX][MAX];
ll suffix_min[MAX];
ll suffix_max[MAX];
ll can_go_till[MAX][MAX+5];
void solve(){     
    ll n; cin>>n; 
    ll shift=n;
    for(ll i=-n;i<=0;i++){
        can_go_till[0][shift+i]=0;
    }
    string s,t; cin>>s>>t;
    s=" "+s,t=" "+t;
    ll sum=0;
    for(ll i=1;i<=n;i++){
        sum+=2*(t[i]-'0')-1;
    }
    suffix_max[0]=0;
    if(sum>=0){   
        for(ll i=1;i<=n;i++){
            s[i]='0'+'1'-s[i];  
            t[i]='0'+'1'-t[i];
        }    
    }
    ll max_sum=0;
    for(ll i=1;i<=n;i++){
        max_sum+=2*(t[i]-'0')-1;
        max_sum=max(0,max_sum);
        suffix_max[i]=max_sum;
    }  
    for(ll i=1;i<=n;i++){
        sum=0;
        for(ll j=-n;j<=0;j++){
            can_go_till[i][shift+j]=i+1;
        }
        for(ll j=i;j>=1;j--){
            sum+=2*(t[j]-'0')-1;
            ll use=min(sum,0);
            can_go_till[i][shift+use]=j;
        }
        for(ll j=n-1;j>=0;j--){
            can_go_till[i][j]=min(can_go_till[i][j],can_go_till[i][j+1]);
        }
    }
    for(ll i=0;i<=n+1;i++){
        for(ll j=0;j<=n+1;j++){
            dp[i][j]=MOD;
        }
    }
    dp[0][0]=0;
    vector<ll> best(n+5,MOD);
    best[0]=0;
    for(ll i=1;i<=n;i++){
        for(ll l=0;l<=i-1;l++){ 
            dp[i][l+1]=dp[i-1][l]+(t[i]=='0');
        }
        for(ll l=0;l<=i;l++){
            ll new_sum=l+2*(t[i]-'0')-1;  
            if(s[i]=='1' and new_sum<=-1){
                continue; 
            }    
            new_sum=max(0,new_sum); 
            dp[i][new_sum]=min(dp[i][new_sum],dp[i-1][l]);
        }
        suffix_min[i]=MOD;
        for(ll j=i-1;j>=0;j--){
            suffix_min[j]=min(suffix_min[j+1],best[j]);
        }
        ll cnt=0;
        for(ll j=i;j>=1;j--){
            cnt+=(t[j]=='0');
            ll now=i-j+1;
            ll cur_suff_max=now+suffix_max[j-1];
            ll pos=max(0,can_go_till[j-1][shift-now]-1);
            dp[i][cur_suff_max]=min(dp[i][cur_suff_max],suffix_min[pos]+cnt);
        }
        for(ll j=0;j<=n;j++){
            best[i]=min(best[i],dp[i][j]); 
        }
    } 
    ll ans=MOD; 
    s[0]='1';
    for(ll i=n;i>=0;i--){  
        ans=min(ans,best[i]);    
        if(s[i]=='1'){
            cout<<ans<<nline;
            return;  
        }
    }
    return;          
}                                          
